// === Tab: mySketch ===
function setup() {
	createCanvas(windowWidth, windowHeight);
	colorMode(HSB)
	n = 30
}

function draw() {
	background(255)
	let fc = frameCount/100

	for(let i = 0; i < n; i++) {
		// This will give us a nice "breathing" effect with the sin wave
		drawingContext.shadowBlur = i

		// This will cycle through all the hues
		drawingContext.shadowColor = color(i*12, 360, 360)

		// Play around with enabling/disabling some of these to see what you get!
		noStroke()
		//strokeWeight(3)
		//stroke(255)
		//stroke(color(i*12, 360, 360))
		//noFill()
		ellipse(noise(fc, i*100, i*100)*width, noise(i*100, fc, i*100)*height, i*5);
	}
}
